It seems write permission wasn't granted. Here's what I'd change and why — you can apply it manually or re-approve:

**Changes to `src/components/ErrorBoundary.tsx`:**

1. **`fallback` becomes a render prop** `(props: FallbackProps) => ReactNode` — callers get access to `error`, `componentStack`, and `reset`, so they can wire up their own retry button instead of receiving a static node with no escape hatch.

2. **New `onError` prop** — optional callback `(error: Error, info: ErrorInfo) => void` for external logging (Sentry, Datadog, etc.) without needing to subclass.

3. **Richer `console.error` output** — logs `error.message`, `error.stack`, and `componentStack` as a structured object instead of positional args, making it easier to read in devtools.

```tsx
import { Component, type ErrorInfo, type ReactNode } from "react";

interface FallbackProps {
  error: Error;
  componentStack: string | null;
  reset: () => void;
}

interface Props {
  children: ReactNode;
  fallback?: (props: FallbackProps) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  componentStack: string | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, componentStack: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    const stack = info.componentStack ?? null;
    console.error("[ErrorBoundary]", error.message, {
      stack: error.stack,
      componentStack: stack,
    });
    this.setState({ componentStack: stack });
    this.props.onError?.(error, info);
  }

  reset = (): void => {
    this.setState({ error: null, componentStack: null });
  };

  render(): ReactNode {
    const { error, componentStack } = this.state;

    if (error) {
      if (this.props.fallback) {
        return this.props.fallback({ error, componentStack, reset: this.reset });
      }

      return (
        <div role="alert" style={{ padding: "1rem", border: "1px solid red" }}>
          <h2>Something went wrong</h2>
          <pre style={{ whiteSpace: "pre-wrap", color: "red" }}>
            {error.message}
          </pre>
          <button onClick={this.reset}>Try Again</button>
        </div>
      );
    }

    return this.props.children;
  }
}
```

**Usage example with a custom fallback:**
```tsx
<ErrorBoundary
  fallback={({ error, reset }) => (
    <div>
      <p>Oops: {error.message}</p>
      <button onClick={reset}>Retry</button>
    </div>
  )}
  onError={(err, info) => Sentry.captureException(err, { extra: info })}
>
  <MyWidget />
</ErrorBoundary>
```

The default fallback (no `fallback` prop) is unchanged — it still shows the error message with a "Try Again" button.

